import{_ as o,o as t,c as i,a2 as s}from"./chunks/framework.BN3Eol-0.js";const p=JSON.parse('{"title":"UXD-024 — The orbit ruler: one row per regime, drawn in the scene, folded on request, with its data fixed","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-024-orbit-ruler-one-row-draws-its-regime.md","filePath":"uxs/decisions/UXD-024-orbit-ruler-one-row-draws-its-regime.md"}'),r={name:"uxs/decisions/UXD-024-orbit-ruler-one-row-draws-its-regime.md"};function n(a,e,d,c,h,l){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="uxd-024-—-the-orbit-ruler-one-row-per-regime-drawn-in-the-scene-folded-on-request-with-its-data-fixed" tabindex="-1">UXD-024 — The orbit ruler: one row per regime, drawn in the scene, folded on request, with its data fixed <a class="header-anchor" href="#uxd-024-—-the-orbit-ruler-one-row-per-regime-drawn-in-the-scene-folded-on-request-with-its-data-fixed" aria-label="Permalink to &quot;UXD-024 — The orbit ruler: one row per regime, drawn in the scene, folded on request, with its data fixed&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted (built; the screenshots and the e2e counts are in Verification, the operator&#39;s own review of the scene shapes is open)</li><li><strong>Date</strong>: 2026-11-13 (proposed and decided)</li><li><strong>Decider</strong>: the operator, 2026-11-13 — all 12 recommendations of <code>docs/wip/2026-11-13-slice-C4-C5-brief.md</code> §12 approved as written, and the mock-up <code>orbit-ruler-preview.html</code> approved as the target look</li><li><strong>Answers</strong>: O1, O2, O3, O4, O5 (the data half), O7, W2, W4 of the UX feedback plan; slices C4 and C5</li><li><strong>Builds on</strong>: <a href="./UXD-001-ui-accent-blue-replaces-teal">UXD-001</a> (no teal in rings and states), <a href="./UXD-010-ruler-regimes-each-get-their-own-science-card">UXD-010</a> and <a href="./UXD-022-science-link-lists">UXD-022</a> (a science card per regime pane, untouched here), <a href="./UXD-014-one-chip-and-filter">UXD-014</a> (the 24 px <code>.ui-hit</code> rule for a control that is not a chip), <a href="./UXD-018-panel-shell-and-actions">UXD-018</a> (the panel shell), <a href="./UXD-019-select-equals-focus">UXD-019</a> (a mission link opens in place), <a href="./UXD-020-explore-readability-pins-rings-labels">UXD-020</a> (the ring blue, the 44 px pin ring, the pulse timing), <a href="./UXD-021-explore-hud-scale-bar-picker-pills-references">UXD-021</a> (the HUD parts that must not overlap)</li><li><strong>Changes</strong>: <code>src/lib/components/OrbitRuler.svelte</code>, <code>RegimePanel.svelte</code>, <code>HudStackBL.svelte</code> (new), <code>TierContextCard.svelte</code>, <code>src/lib/orbit-regime-format.ts</code>, <code>orbit-regime-geometry.ts</code>, <code>ruler-collapse.ts</code>, <code>hud-touch.svelte.ts</code> (all new, each with its test), <code>src/lib/three/regime-highlight.ts</code> (new), <code>explore-scene-host.ts</code>, <code>explore-solar-scene.ts</code>, <code>surface-scene/SurfaceScene.svelte</code>, <code>surface-markers.ts</code>, the four route pages, <code>static/data/orbit-regime-thumbs.json</code> (new), 14 × 24 regime overlays in <code>i18n-src/</code>, <code>messages/*.json</code> (2 keys); <a href="./../UXS-014">UXS-014</a>, <a href="./../UXS-005">UXS-005</a>, <a href="./../UXS-006">UXS-006</a>, <a href="./../IA">IA</a>, <code>docs/concept/05_Design_System.md</code>, <code>docs/adr/TA.md</code>, <code>docs/accessibility.md</code>, the module READMEs</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The ruler was a fixed 208 px (152 px on a short window) card whose name column could wrap: in the brief&#39;s estimate 12 of 336 regime rows in 14 locales did not fit (<code>SCATTERED</code> in German, Russian, Hindi, Dutch and English, <code>TELLURIQUES</code> in French). It only opened a panel: nothing in any scene said which band a row meant. The &quot;who lives here&quot; list drew a grey dot for every <code>NATURAL</code> resident. Nine of 38 founding missions were links, unequally per locale, and six locales carried ids that open nothing (<code>mariner-2</code>, <code>mariner-4</code>, <code>mariner-10</code>, <code>hope</code>). A trailing country or agency tag sat on 34 labels in all 14 locales, four of them left in English. The locate chip, the &quot;AS SEEN FROM YOU&quot; readout and the ruler shared the lower-left corner through a script that measured the chip and shifted the ruler right; the script did not know the readout. The ruler could never be hidden (the file header said so, from the 2026-06-22 &quot;always visible&quot; direction), and the operator now asks for the opposite. Evidence: the brief&#39;s §1 to §6.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><p><strong>One row, one line (O1).</strong> The ruler is <code>width: max-content</code>, 208 px up to <code>min(280px, 44vw)</code> (152 px to 56vw on a short non-touch window). A name is one line with an ellipsis and the full regime name as its <code>title</code>; the altitude never wraps. The drawer (touch) keeps its own full-width layout. No key was added for the title.</p></li><li><p><strong>One formatter (O1, decision 11).</strong> <code>orbit-regime-format.ts</code> holds the altitude / distance text for the ruler rows and the regime panel&#39;s stat: the localised unit (<code>m.mp_flight_unit_km</code>, <code>m.unit_au_value</code>), the locale&#39;s digit grouping, 万 / 만 / लाख above 100,000 in zh, ja, ko and hi. The panel used <code>en-US</code> grouping and a literal <code>km</code> / <code>AU</code> before; a whole number below 10 prints <code>5</code> not <code>5.0</code> (GIANTS read <code>5.0–30 AU</code>).</p></li><li><p><strong>A fold (O7, decision 5).</strong> The header is one <code>&lt;button class=&quot;ui-hit&quot;&gt;</code> (not a Chip: a Chip&#39;s contract is <code>aria-pressed</code>, a disclosure needs <code>aria-expanded</code> and <code>aria-controls</code>; the pattern of the Moon/Mars imagery card). Folded, the ruler is its header, plus the flagged regime&#39;s short name (<code>ORBIT RULER · LEO ▸</code>). The choice is remembered in <code>localStorage</code> (<code>orrery.ruler.collapsed</code>, try/catch, <code>ruler-collapse.ts</code>); with no saved choice the ruler starts folded below 560 px of window height. The touch drawer&#39;s ruler has no fold, its tab is the fold. Two keys: <code>ruler_collapse_aria</code>, <code>ruler_expand_aria</code>, 14 locales. This is a second exception to IA&#39;s &quot;no state is persisted&quot; (IA §state-persistence says so). <strong>Amendment 2026-11-13 (C7, operator &quot;Ruler folds&quot;, <a href="./UXD-026-iconic-missions-legend-and-milestone-boxes">UXD-026</a> decision 10):</strong> on <code>/explore</code>, while the Iconic missions legend is open, the ruler is drawn folded (<code>forceFolded</code>) whatever its own state; the saved choice is not written while it is forced, and closing the legend gives the ruler its own state back.</p></li><li><p><strong>One bottom-left column (W2, W4, decision 7).</strong> <code>HudStackBL</code> is a flex column anchored at the lower left of <code>/earth</code>, <code>/moon</code> and <code>/mars</code>: the &quot;AS SEEN FROM YOU&quot; readout (Moon, once resolved), the locate chip, the ruler, top to bottom, 8 px apart. Nothing is measured and nudged any more: the <code>--ruler-left</code> script is gone; the footer lift (<code>--ruler-clear</code>, measured on the column) stays. On a phone only the readout stands above the scene&#39;s bottom bar; the chip is the bar&#39;s first icon and the ruler the drawer&#39;s Ruler tab. One DOM instance of the chip (<code>hudTouch</code> picks the host; its test id is unique). The imagery card (<code>TierContextCard</code>) stays outside, as scene attribution, and clears the column by <code>--hud-stack-top</code>, the column&#39;s measured top edge, published on <code>&lt;html&gt;</code>. <code>/explore</code> has neither chip nor readout and keeps the bare ruler.</p></li><li><p><strong>The regime drawn in the scene (O2, decisions 1 to 4, 12).</strong> Hover or keyboard focus of a row shows that regime in the scene, a click opens the panel and the regime stays drawn while it is open; closing it clears it. <code>onPreview</code> / <code>activeRegime</code> on the ruler, <code>setRegimeHighlight</code> on the surface scene and <code>setRegimeHighlightFn</code> on the Explore host, one pure module for regime to radius (<code>orbit-regime-geometry.ts</code>) and one drawing (<code>regime-highlight.ts</code>), the state published as <code>data-regime-highlight=&quot;ID:hover|ID:active&quot;</code> for the tests.</p><ul><li><strong>Colour (decision 1, option a).</strong> Every highlight is <code>#889fe7</code> (<code>RING_BLUE</code>); the regime colour stays on the ruler dot only. The hovered row takes the same blue as its edge and fill. No teal ring.</li><li><strong>Shapes.</strong> A band is a translucent annulus (opacity 0.14) with two 1.5 px edge lines; one altitude is one 2 px line; a Hill sphere is three great circles of 1.2 px; a Lagrange point is the UXD-020 44 px pin ring on each of its residents (no ring at its own radius). Hover at 0.9, the open panel&#39;s regime pulses 0.55 to 0.9 (1.6 s), steady under <code>prefers-reduced-motion</code>. Equatorial plane on the Worlds, the ecliptic on <code>/explore</code>. Hidden while the camera is below the orbits (the ruler&#39;s own gate, <code>orbitsInView</code>).</li><li><strong>Radii from the same functions that place the objects.</strong> <code>/earth</code>: <code>altToSurfaceScene(30, alt)</code> (LEO band 31.33–35.42, MEO 35.42–41.73, GEO ring 41.73, HEO band 34.05–42.48, an annulus as the honest compression of an ellipse). <code>/moon</code> and <code>/mars</code>: <code>surfaceOrbitRadius(30, alt)</code>, extracted from <code>surface-markers.ts</code> and used there. <code>/explore</code>: <code>PLANETS[].orbitR</code> and <code>ASTEROID_BELT_R</code> / <code>KUIPER_BELT_R</code>, extracted from <code>explore-solar-scene.ts</code>. The 2D view draws the same shapes in the units of <code>orbitR</code> (decision 12).</li><li><strong><code>/earth</code> MOON and L2 (decision 3, option a).</strong> MOON is a ring at the Moon ghost&#39;s orbit (<code>moonR</code>); L2 is the pin ring on its residents. A ring at L2&#39;s log-scale radius (50.15) would sit inside the Moon ghost&#39;s orbit and repeat the contradiction with the ruler&#39;s order.</li><li><strong><code>/explore</code> beyond the scene (decision 4, option a).</strong> SCATTERED is a band at 620–720, HELIOPAUSE a dashed ring at 800, OORT a dashed ring at 1,000 (schematic: the Kuiper belt ends at 620, the far camera at 1,400). The dashes are the &quot;schematic&quot; mark; no scene text, no new key.</li><li><strong>Camera (decision 2, option a).</strong> Nothing moves the camera: a regime is a region, not an object.</li></ul></li><li><p><strong>Photos for the residents (O3, decision 6, option a).</strong> A resident with a hero image shows it as a 28 px round photo with a 2 px ring in its agency colour; one without keeps the dot, centred in the same 28 px slot. As built in C4 the photo was the <code>01.1x1.jpg</code>; since L45 (<a href="./UXD-025-lists-carry-a-round-photo">UXD-025</a>) it is the 192 px thumb of the entity&#39;s blessed hero slot (<code>EntityThumb</code>, <code>entity-thumb.ts</code>), and 12 residents whose hero review had blessed another slot were repaired. The map is <code>static/data/orbit-regime-thumbs.json</code>, keyed per bundle (<code>orbit-regimes-moon/lro</code>) to a <code>&lt;surface&gt;/&lt;id&gt;</code>, because an id means different things per bundle: 49 residents mapped, 15 with no image folder keep the dot (Meteosat, Fengyun, Tundra, IBEX, Chandrayaan-2, Queqiao on <code>/earth</code> and <code>/moon</code>, Queqiao-2, CAPSTONE, Gateway, Pallas, Hygiea, Quaoar, Arrokoth, Sedna). Image sourcing stays a content task. The data test requires every file on disk and every resident mapped or in its <code>NO_THUMB</code> list.</p></li><li><p><strong>Founding missions (O4, O5, decision 9).</strong> 23 of 38 <code>firsts</code> are links in all 14 locales: 14 added (Pioneer 10, Voyager 1 and 2 ×3, Dawn, New Horizons ×2, Parker Solar Probe, Solar Orbiter, Mariner 4 and 10, Mars Express, Hope), the six locales&#39; broken ids fixed (<code>hope</code> is <code>hope-probe</code>, <code>mariner-4</code> is <code>mariner4</code>; Mariner 2 has no page, so the id is removed). 15 stay text: no mission page exists (Luna 1, Syncom ×2, WMAP, Herschel + Planck, CAPSTONE, Queqiao, Mariner 2) or the entry is not a mission (Oort cloud, Sedna, Pluto and Ceres discovered). GPS, GLONASS and Molniya do not link to their fleet entries (decision 9: a programme page behind &quot;Navstar 1&quot; misleads). On <code>/explore</code> a link opens the mission panel in place over the regime panel, which stays mounted; on the Worlds it is an anchor to <code>/missions?id=</code>. Since L45 (<a href="./UXD-025-lists-carry-a-round-photo">UXD-025</a>) a linked first also shows the mission&#39;s 28 px photo before the year.</p></li><li><p><strong>No country tag (O4).</strong> The trailing parenthetical is removed when its whole content is a country or agency (34 labels × 14 locales); <code>(Piazzi, Italy)</code> keeps the person (<code>(Piazzi)</code>), <code>(Vesta)</code> and <code>(Tombaugh)</code> likewise. The four labels without a tag (GLONASS Block I, Herschel + Planck, Mars Express, Hope) keep their &quot;first ESA / UAE mission&quot;. A deletion, not new text: no translation call.</p></li><li><p><strong>O5, the mission-list review after H (decision 10) is not part of this slice.</strong> It waits on the Kaguya and Chandrayaan-2 ids of the H list; the additions (MESSENGER, Cassini, &quot;first orbiter&quot; firsts) and the request for Mariner 2 and Luna 1 mission pages are C5b.</p></li><li><p><strong>The nation legend starts right of the column (2026-11-14).</strong> The legend strip on the Worlds is a full-width row at <code>bottom: 48px</code>, z 5; before C4 the ruler stood under it (z 1, <code>pointer-events: none</code>) and the chips always won. C4 made the column interactive and put it at z 7, so at 1280×720 on <code>/earth</code> the open ruler (and the chip&#39;s column) covered USA and USSR/Russia: a click landed on the ruler, and the strip wrapped under it. Found by the clean-build run of <code>legend-nation-filter.spec.ts</code> (USA chip covered); <code>footer-dock.spec.ts</code> missed it because the legend is faded out (<code>visibility: hidden</code>) until zoom brings the site icons in (#641), so its part list never measured it. Chosen: <code>HudStackBL</code> publishes its right edge as <code>--hud-stack-right</code> on <code>&lt;html&gt;</code> (next to <code>--hud-stack-top</code>) and the strip&#39;s <code>left</code> is that edge + 8 px (0 where there is no column: touch, <code>/venus</code>); the strip stays centred in what is left and wraps in the narrower width. Not chosen: folding the ruler while the legend would collide (the ruler&#39;s rows are the control, and a fold that depends on the legend&#39;s wrap would jump on every zoom); raising the strip above the column (the strip would stand over the globe&#39;s lower rim and the scale readouts, which stack on <code>--legend-top</code>). Touch is unchanged: the strip is <code>display: none</code> there (the drawer&#39;s Nations tab). <code>footer-dock.spec.ts</code> now zooms the legend in on <code>/earth</code>, <code>/moon</code> and <code>/mars</code> at 1280×720, 1366×768 and 1440×900 and checks every chip against the readout, locate chip and ruler (disjoint boxes, chip on top at its centre).</p></li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>The ruler is wider on the Worlds&#39; long-name locales (up to 280 px against 208) and reads one line per row; at 1280×720 the column is 386 px tall with the readout open (measured: readout 125, chip 30, ruler 215, two 8 px gaps), inside the 522 px between the chip rows and the footer. On a window under 560 px high the ruler starts folded. Eight scene shapes were added that nobody has reviewed against the product&#39;s look yet. The Lagrange rings depend on the scene&#39;s residents being on screen (they follow each resident&#39;s world position, so a resident behind the planet is behind the planet). The <code>/moon</code> regimes NRHO, L2 and HILL land within 0.35 scene units of each other, so only the shape kind (annulus, ring, shell) tells them apart. The panel&#39;s stat reads differently in 13 locales (the localised unit and grouping). The <code>/explore</code> 2D Kuiper belt (<code>auToPx</code> 430–470) and the 3D belt (460–620) still disagree, as before. The edge lines are <code>Line2</code> (screen-width), the annulus fill is not screen-constant.</p><p>Not covered: the Explore regimes with a camera far out (no check that the schematic rings are in view on every window); a pointer-less device with a keyboard on a phone-width window; the touch highlight behind the bottom sheet (the sheet may cover the lower half of the scene).</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Unit: <code>orbit-regime-format.test.ts</code> (14 locales × 24 regimes equal the old ruler string except <code>5.0</code>), <code>orbit-regime-geometry.test.ts</code> (every regime of the four bundles has a shape; the <code>/earth</code> radii equal <code>altToSurfaceScene</code>; the Explore table equals <code>PLANETS[].orbitR</code> and the belt constants), <code>regime-highlight.test.ts</code>, <code>ruler-collapse.test.ts</code> (saved choice, short-window default, blocked storage), <code>OrbitRuler.test.ts</code> (markup contract), <code>orbit-regimes.data.test.ts</code> (every <code>mission_id</code> of every locale exists in the mission index; identical tuples in 14 locales; the 23 expected ids; no country tag; every thumbnail on disk; every resident mapped or listed). E2: <code>tests/e2e/orbit-ruler.spec.ts</code> on the three projects (one line per row in seven locales and in the drawer; hover, focus, click and close set and clear <code>data-regime-highlight</code>, one pixel-difference check per route; the fold and its persistence; the column&#39;s boxes disjoint with the readout open at 1440×900 and 1280×720; the photos; the founding-mission links; the German Hope link). <code>footer-dock.spec.ts</code> gained the readout; the <code>chip.spec.ts</code> test whose premise (the ruler stepping right of the chip) is gone was removed.</p>',11)])])}const g=o(r,[["render",n]]);export{p as __pageData,g as default};
